/*
 * mod-playerbots: SimulationCraft action priority lists (APL) as bot rotations.
 *
 * The owner's request (2026-11-05): the rotations and talents of SimC's T21 profiles, the default profile of
 * each spec, instead of hand-written lists. The profiles are built into the module (AplProfiles.cpp,
 * generated by tools/simc_to_apl.py from apl/*.simc); files in Playerbots.Rotation.Directory override them.
 *
 * Each `actions[.list]=` line is parsed once at startup into actions with an `if=` expression tree. Every combat
 * check the bot walks its main list (call_action_list / run_action_list / variable as SimC does) and casts the
 * first spell it knows whose condition holds and that BotCast accepts. Expressions read the bot's state on its
 * own thread: resources, auras, cooldowns, charges, talents, target health, enemy counts, combat time, its last
 * casts. Owner's decisions: `artifact.*` counts as learned (artifacts come later), gear / set bonus / trinket
 * terms count as false, raid events never happen. Anything the interpreter does not know is 0, and reported at
 * startup per spec.
 */

#ifndef MOD_PLAYERBOTS_BOTAPL_H
#define MOD_PLAYERBOTS_BOTAPL_H

#include "Define.h"
#include "ObjectGuid.h"
#include "BotCombat.h"
#include <deque>
#include <map>
#include <set>
#include <string>
#include <unordered_map>
#include <vector>

class Player;
class Unit;

namespace BotApl
{
    struct BuiltInProfile
    {
        uint32 specId;
        char const* name;
        char const* talents;            // SimC talents= string: one digit per row, the column (1-3), 0 = none
        char const* const* lines;       // actions lines, nullptr-terminated
    };
    extern BuiltInProfile const BuiltInProfiles[];

    // Per bot: what the interpreter remembers between checks. Used on the bot's thread only.
    struct State
    {
        std::map<std::string, double> variables;
        std::unordered_map<std::string, uint32> known;  // normalized spell name -> id the bot knows (0 = none)
        uint32 knownCheckedAt = 0;                      // getMSTime of the last cache reset
        bool inCombat = false;
        uint32 combatStart = 0;
        std::deque<std::string> lastCasts;              // normalized names, newest first
        ObjectGuid ttdTarget;                           // time_to_die estimate
        uint32 ttdStart = 0;
        uint64 ttdHealth = 0;
        uint64 lastHealth = 0;                          // incoming_damage: own health drops
        std::deque<std::pair<uint32, uint32>> damage;   // (getMSTime, damage)
        std::map<uint32, uint32> lineCooldowns;         // action id -> getMSTime it was used (line_cd)
        bool burnPhase = false;                         // Arcane's start/stop_burn_phase
        uint32 burnStart = 0;
        uint32 precombatTimer = 0;
        // out of combat: spell id -> getMSTime it was cast, for spells that leave no aura of their own name on the
        // bot (Totem Mastery summons totems): not cast again for the spell's duration (2 minutes without one)
        std::map<uint32, uint32> precombatCasts;
    };

    // Startup: parses the built-in profiles and the .simc files of directory (when it exists; those replace the
    // built-in profile of their spec), looks their spell names up and logs, per spec, what it could not resolve.
    void Initialize(std::string const& directory);

    bool HasProfile(uint32 specId);
    // the profile's talents= string, nullptr if the spec has no profile
    char const* TalentString(uint32 specId);

    // In combat (target = the enemy): the profile's main list; out of combat (target null): the precombat list's
    // self buffs and pet summons. interruptSpell = the spec's interrupt (normalized name), left to the interrupt
    // code. True when a spell was cast; fired then names it ("Spell (id), list#line").
    bool Run(Player* bot, Unit* target, State& state, BotCombat::SpellThrottle& throttle, std::string const& interruptSpell,
        std::string& fired);

    // a spell or SimC action name as compared everywhere: lower case letters and digits only
    std::string Normalize(std::string const& name);
}

#endif
